#!/usr/bin/env python3
import json
import csv
import zipfile
import shutil
import os
import sys
import copy
import xml.etree.ElementTree as ET

# Paths
SRC = "/root/renewal_playbook.hwpx"
UPDATE_JSON = "/root/renewal_update.json"
FOLLOWUPS_CSV = "/root/followups.csv"
OUT = "/root/renewal_playbook_updated.hwpx"
TMP_DIR = "/tmp/hwpx_work"

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HP_NS}
ET.register_namespace("hp", HP_NS)

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


def read_updates():
    with open(UPDATE_JSON, "r", encoding="utf-8") as f:
        updates = json.load(f)

    required = [
        "customer",
        "owner_name",
        "window_start",
        "window_end",
        "band",
        "escalation_email",
        "note",
    ]
    missing = [k for k in required if k not in updates]
    if missing:
        raise ValueError(f"renewal_update.json missing keys: {missing}")

    return updates


def read_followups():
    with open(FOLLOWUPS_CSV, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return []

    if "sequence" not in rows[0]:
        raise ValueError("followups.csv must contain a 'sequence' column")

    # Item text column name may vary; detect conservatively.
    text_col = None
    for cand in ("item", "text", "content"):
        if cand in rows[0]:
            text_col = cand
            break
    if not text_col:
        raise ValueError("followups.csv must contain one of columns: item, text, content")

    followups = sorted(rows, key=lambda r: int(r["sequence"]))
    items = [r[text_col].strip() for r in followups]
    return items


def unzip_to_tmp():
    if os.path.exists(TMP_DIR):
        shutil.rmtree(TMP_DIR)
    os.makedirs(TMP_DIR, exist_ok=True)

    with zipfile.ZipFile(SRC, "r") as zf:
        zf.extractall(TMP_DIR)


def zip_from_tmp(out_path: str):
    # Recreate zip, preserving relative paths.
    if os.path.exists(out_path):
        os.remove(out_path)

    with zipfile.ZipFile(out_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for root, _dirs, files in os.walk(TMP_DIR):
            for fn in files:
                abs_path = os.path.join(root, fn)
                rel_path = os.path.relpath(abs_path, TMP_DIR)
                # Normalize to ZIP separators
                rel_path = rel_path.replace(os.path.sep, "/")
                zf.write(abs_path, rel_path)


def localname(tag: str) -> str:
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def get_paragraph_text(p_elem) -> str:
    # Concatenate all hp:t texts within the paragraph.
    parts = []
    for t in p_elem.findall(".//hp:t", NS):
        if t.text:
            parts.append(t.text)
    return "".join(parts)


def clear_and_set_paragraph_text(p_elem, new_text: str) -> None:
    """Replace all runs with a single run/t containing new_text."""
    # Remove existing children
    for child in list(p_elem):
        p_elem.remove(child)

    run = ET.Element(f"{{{HP_NS}}}run", {"charPrIDRef": "0"})
    t = ET.SubElement(run, f"{{{HP_NS}}}t")
    t.text = new_text
    p_elem.append(run)


def remove_linesegarrays(p_elem) -> None:
    # Remove any descendant whose localname is linesegarray/lineSegArray (case-insensitive)
    # We have to remove via parent traversal because ElementTree lacks getparent().
    targets = []
    for parent in p_elem.iter():
        for child in list(parent):
            ln = localname(child.tag).lower()
            if ln in ("linesegarray", "linesegarray"):  # same, but keep explicit
                targets.append((parent, child))
    for parent, child in targets:
        parent.remove(child)


def update_section_xml(xml_path: str, updates: dict, followup_items: list[str]) -> dict:
    tree = ET.parse(xml_path)
    root = tree.getroot()

    appendix_before = None
    # Quick check appendix presence
    for p in root.findall(".//hp:p", NS):
        txt = get_paragraph_text(p)
        if txt == APPENDIX_SENTENCE:
            appendix_before = txt
            break

    changed_paragraphs = 0

    # 1) Field replacements based on known labels.
    for p in root.findall(".//hp:p", NS):
        old_full = get_paragraph_text(p)

        if old_full == APPENDIX_SENTENCE:
            continue

        new_full = old_full

        # Customer line
        if old_full.startswith("고객사:"):
            new_full = f"고객사: {updates['customer']}"

        # Owner line
        if old_full.startswith("현 담당자:"):
            new_full = f"현 담당자: {updates['owner_name']}"

        # Renewal window line
        if old_full.startswith("갱신 윈도우:"):
            new_full = f"갱신 윈도우: {updates['window_start']} ~ {updates['window_end']}"

        # Renewal window confirmation line
        if old_full.startswith("갱신 윈도우 확인:"):
            new_full = f"갱신 윈도우 확인: {updates['window_start']} ~ {updates['window_end']}"

        # Pricing note
        if old_full.startswith("가격 메모:"):
            new_full = f"가격 메모: {updates['note']}"

        # Follow-ups are handled in a separate pass; skip here.

        if new_full != old_full:
            clear_and_set_paragraph_text(p, new_full)
            remove_linesegarrays(p)
            changed_paragraphs += 1

    # 2) Table cell updates: band and escalation email live in their own paragraphs.
    # We update by exact old value match, but also by adjacent label if present.
    for p in root.findall(".//hp:p", NS):
        old_full = get_paragraph_text(p)
        if old_full == APPENDIX_SENTENCE:
            continue

        new_full = old_full
        if old_full.strip() in ("Standard-18M", "Standard-12M", "Standard-24M") or "-" in old_full:
            # Conservative: only replace if this paragraph is in the pricing band table cell context.
            # Match exact old sample value too.
            if old_full.strip() == "Standard-18M":
                new_full = updates["band"]

        if old_full.strip().endswith("@northwind.example") or old_full.strip().endswith("@example"):
            if old_full.strip() == "ops-old@northwind.example":
                new_full = updates["escalation_email"]

        if new_full != old_full:
            clear_and_set_paragraph_text(p, new_full)
            remove_linesegarrays(p)
            changed_paragraphs += 1

    # 3) Follow-up replacement.
    followup_ps = []
    for p in root.findall(".//hp:p", NS):
        txt = get_paragraph_text(p)
        if txt.startswith("1. ") or txt.startswith("2. ") or txt.startswith("3. "):
            if "old follow-up" in txt:
                followup_ps.append(p)

    # If we found the old three followups, replace them in order.
    if followup_ps:
        # Ensure stable order by paragraph id attribute if present
        def pid(elem):
            try:
                return int(elem.attrib.get("id", "0"))
            except Exception:
                return 0

        followup_ps.sort(key=pid)

        # We only edit as many paragraphs as we have items; if item count differs, adjust.
        # For this task data, it is expected to be 3.
        parent_map = {c: p for p in root.iter() for c in list(p)}
        first_parent = parent_map.get(followup_ps[0])

        if first_parent is None:
            raise RuntimeError("Could not locate parent for follow-up paragraphs")

        # If counts differ, remove extras / insert clones.
        existing = followup_ps
        desired_n = len(followup_items)

        # Remove extra paragraphs
        if len(existing) > desired_n:
            for extra in existing[desired_n:]:
                first_parent.remove(extra)
            existing = existing[:desired_n]

        # Add missing paragraphs by cloning last existing
        if len(existing) < desired_n:
            if not existing:
                raise RuntimeError("No existing follow-up paragraph to clone")
            template = existing[-1]
            insert_after = template
            for _i in range(desired_n - len(existing)):
                clone = copy.deepcopy(template)
                # Clear its content; set later.
                clear_and_set_paragraph_text(clone, "")
                # Insert after insert_after (ElementTree insert by index)
                idx = list(first_parent).index(insert_after)
                first_parent.insert(idx + 1, clone)
                existing.append(clone)
                insert_after = clone

        # Now set text for each follow-up paragraph
        for i, (p, item) in enumerate(zip(existing, followup_items), start=1):
            old_full = get_paragraph_text(p)
            new_full = f"{i}. {item}"
            if new_full != old_full:
                clear_and_set_paragraph_text(p, new_full)
                remove_linesegarrays(p)
                changed_paragraphs += 1

    # Appendix integrity check
    appendix_after = None
    for p in root.findall(".//hp:p", NS):
        txt = get_paragraph_text(p)
        if txt == APPENDIX_SENTENCE:
            appendix_after = txt
            break

    if appendix_before is None or appendix_after is None:
        raise RuntimeError(f"Appendix sentence not found in {xml_path}")
    if appendix_after != APPENDIX_SENTENCE:
        raise RuntimeError(f"Appendix sentence changed in {xml_path}")

    tree.write(xml_path, encoding="UTF-8", xml_declaration=True)
    return {"xml_path": xml_path, "changed_paragraphs": changed_paragraphs}


def main():
    updates = read_updates()
    followups = read_followups()

    unzip_to_tmp()

    # Walk for content XMLs under Contents/
    contents_dir = os.path.join(TMP_DIR, "Contents")
    if not os.path.isdir(contents_dir):
        raise RuntimeError("Invalid HWPX: missing Contents/")

    xml_paths = []
    for root, _dirs, files in os.walk(contents_dir):
        for fn in files:
            if fn.lower().endswith(".xml"):
                xml_paths.append(os.path.join(root, fn))

    if not xml_paths:
        raise RuntimeError("No XML files found under Contents/")

    stats = []
    for xp in sorted(xml_paths):
        # Only edit section XMLs; leave other XMLs untouched unless needed.
        base = os.path.basename(xp)
        if base.startswith("section") and base.endswith(".xml"):
            stats.append(update_section_xml(xp, updates, followups))

    zip_from_tmp(OUT)

    # Quick ZIP validity check
    with zipfile.ZipFile(OUT, "r") as zf:
        zf.testzip()

    print("Wrote", OUT)
    for s in stats:
        print(f"- {os.path.relpath(s['xml_path'], TMP_DIR)}: changed_paragraphs={s['changed_paragraphs']}")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print("ERROR:", e, file=sys.stderr)
        sys.exit(1)

